package rs.unicredit.cardlifecycle.authorization;

import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;

// 2. Komponenta za proveru pristupa
@Component("authz")
class RoleChecker {

    private final RolesProperties rolesProperties;

    public RoleChecker(RolesProperties rolesProperties) {
        this.rolesProperties = rolesProperties;
    }

    public boolean hasAnyAllowedRole(Authentication auth, String controllerName) {
        var allowed = rolesProperties.getRolesFor(controllerName);
        return auth.getAuthorities().stream()
                .anyMatch(a -> allowed != null && allowed.contains(a.getAuthority()));
    }

    public boolean hasAnyOfAllowedRole(Authentication auth, String... roleGroups) {
        List<String> allowedRoles = new ArrayList<>();

        // Dodajemo role iz svih navedenih grupa
        for (String roleGroup : roleGroups) {
            List<String> roles = rolesProperties.getRolesFor(roleGroup);
            if (roles != null) {
                allowedRoles.addAll(roles);
            }
        }

        return auth.getAuthorities().stream()
                .anyMatch(a -> allowedRoles.contains(a.getAuthority()));
    }

    public boolean hasSpecificRoleByIndex(Authentication auth, String controllerName, int index) {
        var allowed = rolesProperties.getRolesFor(controllerName);
        if (allowed == null || index >= allowed.size()) return false;
        String role = allowed.get(index);
        return auth.getAuthorities().stream()
                .anyMatch(a -> a.getAuthority().equals(role));
    }
}

