			String selectQuery = "SELECT TRPANO, TRACCY, TRSQNO, TRACNO, TRCOPU, TRACNP, TRCOPP FROM BEZVD02.CCTR00";
			PreparedStatement stmt = conDb2.prepareStatement(selectQuery);
			ResultSet rs = stmt.executeQuery();

			// Priprema batch insert-a
			String insertQuery = "INSERT INTO TBL_CCTR00 (TRPANO, TRACCY, TRSQNO, TRACNO, TRCOPU, TRACNP, TRCOPP) VALUES (?, ?, ?, ?, ?, ?, ?)";
			PreparedStatement oracleStmt = conOracle.prepareStatement(insertQuery);

			int batchSize = 1000;
			int count = 0;

			while (rs.next()) {
				oracleStmt.setLong(1, rs.getLong("TRPANO"));
				oracleStmt.setString(2, rs.getString("TRACCY"));
				oracleStmt.setInt(3, rs.getInt("TRSQNO"));
				oracleStmt.setLong(4, rs.getLong("TRACNO"));
				oracleStmt.setString(5, rs.getString("TRCOPU"));
				oracleStmt.setLong(6, rs.getLong("TRACNP"));
				oracleStmt.setString(7, rs.getString("TRCOPP"));

				oracleStmt.addBatch();
				count++;

				if (count % batchSize == 0) {
					oracleStmt.executeBatch();
					logger.info("Migrirano {} slogova...", count);
				}
			}

			// IzvrÅ¡i preostale podatke
			oracleStmt.executeBatch();
			conOracle.commit();

			// Brojanje slogova u AS400
			String countAS400Query = "SELECT COUNT(*) FROM BEZVD02.CCTR00";
			PreparedStatement stmtAS400 = conDb2.prepareStatement(countAS400Query);
			ResultSet rsAS400 = stmtAS400.executeQuery();
			rsAS400.next();
			int totalAS400 = rsAS400.getInt(1);

			// Brojanje slogova u Oracle
			String countOracleQuery = "SELECT COUNT(*) FROM TBL_CCTR00";
			PreparedStatement stmtOracle = conOracle.prepareStatement(countOracleQuery);
			ResultSet rsOracle = stmtOracle.executeQuery();
			rsOracle.next();
			int totalOracle = rsOracle.getInt(1);

			// Zatvaranje konekcija
			rs.close();
			stmt.close();
			conDb2.close();
			oracleStmt.close();
			conOracle.close();
			rsAS400.close();
			stmtAS400.close();
			rsOracle.close();
			stmtOracle.close();

			long endTime = System.currentTimeMillis();
			logger.info("*********************** END migrateCCTR00 ****************");
			logger.info("AS400 COUNT: {}, Oracle COUNT: {}", totalAS400, totalOracle);
			logger.info("Ukupno trajanje: {} sekundi", (endTime - startTime) / 1000);

			// VraÄ‡anje rezultata
			if (totalAS400 == totalOracle) {
				logger.info("Migracija uspeÅ¡na! Broj slogova se poklapa.");
				return "SUCCESS";
			} else {
				logger.warn("Razlika u broju slogova! AS400: {}, Oracle: {}", totalAS400, totalOracle);
				return "ERROR";
//				return "GreÅ¡ka: Broj slogova se ne poklapa! AS400: " + totalAS400 + ", Oracle: " + totalOracle;
			}

		} catch (Exception e) {
			logger.error("GreÅ¡ka prilikom migracije: ", e);
			return "ERROR";
//			return "GreÅ¡ka prilikom migracije: " + e.getMessage();
		}
	}

	@Override
